mapper.insert:
INSERT INTO scheduled_agent_task (
    name, prompt, schedule_type, schedule_expr,
    enabled, next_run_at
) VALUES (
    #{name}, #{prompt}, #{scheduleType}, #{scheduleExpr},
    #{enabled}, #{nextRunAt}
)

mapper.select:
SELECT id FROM scheduled_agent_task
WHERE enabled = 1
  AND next_run_at <= #{now}
  AND (lock_until IS NULL OR lock_until < #{now})
ORDER BY next_run_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE scheduled_agent_task
SET lock_until = #{lockUntil},
    lock_owner = #{lockOwner},
    update_time = #{now}
WHERE id = #{id}
  AND (lock_until IS NULL OR lock_until < #{now})
  AND enabled = 1
  AND next_run_at <= #{now}

UPDATE scheduled_agent_task
SET lock_until = #{lockUntil},
    lock_owner = #{lockOwner},
    update_time = #{now}
WHERE id = #{id}
  AND (lock_until IS NULL OR lock_until < #{now})

UPDATE scheduled_agent_task
SET lock_until = NULL,
    lock_owner = NULL,
    next_run_at = #{nextRunAt},
    last_run_at = #{finishedAt},
    last_status = #{lastStatus},
    last_error = #{lastError},
    update_time = #{finishedAt}
WHERE id = #{id}
  AND lock_owner = #{lockOwner}
